//! Facts about Ignition 8.3 generated by introspecting a real gateway.
//!
//! * the `system.*` scripting API per scope (functions with their overloads,
//!   constants, objects and packages),
//! * the expression functions with their accepted argument counts,
//! * the Perspective component types with their property schemas,
//! * the names in Jython's `__builtin__` module,
//! * which Perspective components can run code in the browser
//!   ([`client_code`], measured on the client bundles).
//!
//! The data lives in `data/*.json` and is compiled into static tables
//! (`src/generated.rs`), so nothing is parsed at run time. Both are produced
//! by `stubs-gen/run.sh`.
//! Only facts are stored (names, types, arities, defaults), no documentation
//! text; [`Function::docs_url`] and [`ExpressionFunction::docs_url`] point to
//! the official documentation instead.

pub mod client_code;
#[rustfmt::skip]
mod generated;
mod schema;
mod system;

pub use schema::{
    Additional, ComponentEvent, ComponentType, ExtensionFunction, SHARED_SCHEMA_PREFIX, Schema,
    TypeSet, meta_prop, shared_prop, shared_schemas,
};
pub use system::{
    ArityError, ConstValue, Constant, ConstantVariant, Function, FunctionVariant, Member,
    ObjectKind, ObjectVariant, Overload, OverloadKind, Package, Param, ScriptObject, check_call,
    system_constant, system_function, system_member, system_members, system_object, system_package,
    system_packages, system_path_listed,
};

/// Ignition version the data was generated from, e.g. `8.3.3`.
pub const IGNITION_VERSION: &str = generated::IGNITION_VERSION;
/// Full gateway version string including the build, e.g. `8.3.3 (b2026012009)`.
pub const IGNITION_BUILD: &str = generated::IGNITION_BUILD;
/// Jython version of the gateway, e.g. `2.7.3`.
pub const JYTHON_VERSION: &str = generated::JYTHON_VERSION;

/// Where a script runs.
///
/// Perspective session, view and component scripts run in the gateway, so
/// they use [`Scope::Gateway`] (including `system.perspective.*`).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Scope {
    /// Gateway scope: gateway events, tag events, WebDev, Perspective.
    Gateway,
    /// Vision Client scope.
    Client,
    /// Designer scope (script console, Vision in the Designer).
    Designer,
}

impl Scope {
    /// All scopes.
    pub const ALL: [Scope; 3] = [Scope::Gateway, Scope::Client, Scope::Designer];

    const fn bit(self) -> u8 {
        match self {
            Scope::Gateway => 1,
            Scope::Client => 2,
            Scope::Designer => 4,
        }
    }
}

/// A set of [`Scope`]s.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Default)]
pub struct Scopes(u8);

impl Scopes {
    /// The empty set.
    pub const NONE: Scopes = Scopes(0);
    /// Gateway, Client and Designer.
    pub const ALL: Scopes = Scopes(7);

    pub(crate) const fn from_bits(bits: u8) -> Scopes {
        Scopes(bits)
    }

    /// Whether `scope` is in the set.
    pub const fn contains(self, scope: Scope) -> bool {
        self.0 & scope.bit() != 0
    }

    /// Union of two sets.
    #[must_use]
    pub const fn union(self, other: Scopes) -> Scopes {
        Scopes(self.0 | other.0)
    }

    /// Whether the set is empty.
    pub const fn is_empty(self) -> bool {
        self.0 == 0
    }

    /// The scopes in the set.
    pub fn iter(self) -> impl Iterator<Item = Scope> {
        Scope::ALL.into_iter().filter(move |s| self.contains(*s))
    }
}

impl From<Scope> for Scopes {
    fn from(scope: Scope) -> Scopes {
        Scopes(scope.bit())
    }
}

/// Accepted argument counts of an expression function: `min`, `min + step`,
/// ... up to `max` (`None` = no upper bound).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Arity {
    pub min: u8,
    pub max: Option<u8>,
    pub step: u8,
}

impl Arity {
    /// Whether a call with `count` arguments compiles.
    pub fn accepts(&self, count: usize) -> bool {
        let min = usize::from(self.min);
        if count < min {
            return false;
        }
        if self.max.is_some_and(|max| count > usize::from(max)) {
            return false;
        }
        (count - min).is_multiple_of(usize::from(self.step.max(1)))
    }
}

/// An expression function registered in the gateway (the function set used
/// by Perspective bindings and expression tags).
#[derive(Debug)]
pub struct ExpressionFunction {
    /// Name as registered, e.g. `dateFormat`.
    pub name: &'static str,
    /// Lowercase lookup key; Ignition resolves function names
    /// case-insensitively.
    pub key: &'static str,
    /// Category paths, e.g. `Date and Time/add<field>`.
    pub categories: &'static [&'static str],
    /// Accepted argument counts as enforced when the expression is compiled.
    /// `None` when no count is accepted at all.
    pub arity: Option<Arity>,
    /// Parameter hint as shown by the Designer, e.g. `number, [decimals]`.
    pub params: &'static str,
}

impl ExpressionFunction {
    /// Whether a call with `count` arguments compiles.
    pub fn accepts_arg_count(&self, count: usize) -> bool {
        self.arity.is_some_and(|a| a.accepts(count))
    }

    /// Link to the official documentation page of this function.
    pub fn docs_url(&self) -> String {
        let category = self.categories.first().copied().unwrap_or("");
        let category = category.split('/').next().unwrap_or("");
        format!(
            "https://www.docs.inductiveautomation.com/docs/8.3/appendix/expression-functions/{}/{}",
            slug(category),
            self.name
        )
    }
}

/// Looks up an expression function by name, case-insensitively.
pub fn expression_function(name: &str) -> Option<&'static ExpressionFunction> {
    generated::EXPRESSION_FUNCTIONS
        .binary_search_by(|f| cmp_ascii_lowercase(f.key, name))
        .ok()
        .map(|i| &generated::EXPRESSION_FUNCTIONS[i])
}

/// All expression functions, sorted by lowercase name.
pub fn expression_functions() -> &'static [ExpressionFunction] {
    generated::EXPRESSION_FUNCTIONS
}

/// Looks up a Perspective component type by id, e.g. `ia.display.label`.
pub fn component_type(id: &str) -> Option<&'static ComponentType> {
    generated::COMPONENT_TYPES
        .binary_search_by(|c| c.id.cmp(id))
        .ok()
        .map(|i| &generated::COMPONENT_TYPES[i])
}

/// All Perspective component types, sorted by id.
pub fn component_types() -> &'static [ComponentType] {
    generated::COMPONENT_TYPES
}

/// A shared Perspective schema by file name, e.g.
/// `style-properties.schema.json`. Component schemas refer to these as
/// `urn:ignition-schema:schemas/<name>`. Also contains `meta-schema.json`
/// (the `meta` of every component) and `view-props-schema.json`.
pub fn shared_schema(name: &str) -> Option<&'static Schema> {
    generated::SHARED_SCHEMAS
        .binary_search_by(|(n, _)| (*n).cmp(name))
        .ok()
        .map(|i| generated::SHARED_SCHEMAS[i].1)
}

/// What a name in Jython's `__builtin__` module is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BuiltinKind {
    Type,
    Function,
    Exception,
    Constant,
}

/// A name in Jython's `__builtin__` module.
#[derive(Debug)]
pub struct Builtin {
    pub name: &'static str,
    pub kind: BuiltinKind,
}

/// The names in Ignition's Jython `__builtin__` module, sorted.
pub fn jython_builtins() -> &'static [Builtin] {
    generated::BUILTINS
}

/// Whether `name` is in Ignition's Jython `__builtin__` module.
pub fn is_jython_builtin(name: &str) -> bool {
    generated::BUILTINS
        .binary_search_by(|b| b.name.cmp(name))
        .is_ok()
}

fn cmp_ascii_lowercase(key: &str, probe: &str) -> std::cmp::Ordering {
    key.bytes()
        .cmp(probe.bytes().map(|b| b.to_ascii_lowercase()))
}

pub(crate) fn slug(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        if c.is_ascii_alphanumeric() {
            out.push(c.to_ascii_lowercase());
        } else if !out.ends_with('-') && !out.is_empty() {
            out.push('-');
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    out
}

